<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $counts = sd_dashboard_counts(); ?><section class="sd-dashboard-card"><div class="sd-card-heading"><h2><?php esc_html_e( 'Your overview', 'social-discovery' ); ?></h2><a href="<?php echo esc_url( sd_auth_profile_url() ); ?>"><?php esc_html_e( 'View profile', 'social-discovery' ); ?></a></div><div class="sd-summary-grid"><?php foreach ( array( 'communities' => __( 'Communities', 'social-discovery' ), 'connections' => __( 'Connections', 'social-discovery' ), 'notifications' => __( 'Unread notifications', 'social-discovery' ), 'messages' => __( 'Unread messages', 'social-discovery' ), 'saved' => __( 'Saved posts', 'social-discovery' ) ) as $key => $label ) : ?><div class="sd-summary-item"><strong><?php echo null === $counts[ $key ] ? '—' : esc_html( $counts[ $key ] ); ?></strong><span><?php echo esc_html( $label ); ?></span></div><?php endforeach; ?></div></section>
